import React, { useState, useEffect } from 'react';
import './Board.css';
import { getValueFromCoordinates, getCoordinatesFromValue } from './coordinates.js';

const Board = ({ gameData, socket }) => {
  const gridSize = 11; // Velikost desky
  const centerIndex = Math.floor(gridSize / 2); // Středový index pro křížový tvar

  const { pieces: initialPieces } = gameData.board;
  const { players } = gameData;

  const [pieces, setPieces] = useState(initialPieces); // Uložení pozic figurek
  const [loading, setLoading] = useState(false); // Příznak pro sledování, zda je tah v procesu
  const [error, setError] = useState(null); // Uložení chybových zpráv
  const [statusMessage, setStatusMessage] = useState(""); // Zpráva o stavu
  const [diceRoll, setDiceRoll] = useState(null); // Výsledek hodu kostkou

  useEffect(() => {
    if (!socket) return;

    // Event listenery pro připojení a odpojení socketu
    socket.on('connect', () => {
      console.log('Socket připojen: ', socket.id);
    });

    socket.on('disconnect', () => {
      console.log('Odpojeno od serveru.');
    });

    // Zpracování aktualizací hry
    socket.on('game:updated', (data) => {
      const { updatedPiece, nextPlayerId } = data;

      if (updatedPiece) {
        const { ownerId, color, commonPosition } = updatedPiece;
        console.log(`Hráč ${ownerId} přesunul ${color} figurku na pozici ${commonPosition}`);

        // Aktualizace pozice figurky ve stavu
        setPieces(prevPieces =>
          prevPieces.map(piece =>
            piece.ownerId === ownerId && piece.color === color
              ? { ...piece, position: commonPosition }
              : piece
          )
        );

        if (nextPlayerId) {
          setStatusMessage(`Je na tahu hráč ${nextPlayerId}.`);
        }
      }
    });

    // Zpracování hodů kostkou
    socket.on('game:diceRolled', (data) => {
      const { playerId, dice, canDeploy } = data;
      setDiceRoll(dice);
      setStatusMessage(`Hráč ${playerId} hodil ${dice}.`);

      if (canDeploy) {
        setStatusMessage(`Hráč ${playerId} může nasadit novou figurku!`);
      }
    });

    // Úklid event listenerů při odpojení komponenty
    return () => {
      socket.off('game:updated');
      socket.off('game:diceRolled');
    };
  }, [socket]);

  // Funkce pro zjištění, jestli je dlaždice součástí křížového tvaru
  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) {
      return false;
    }

    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  // Funkce pro určení barvy dlaždice podle pozice hráče
  const getTileColor = (row, col) => {
    if (!isCrossTile(row, col)) return 'white';
    let color = 'white';

    players.forEach(player => {
      if (player.color === 'red' && ((row === 4 && col === 0) || (row === 5 && col >= 1 && col <= 4) || (row >= 0 && row <= 1 && col >= 0 && col <= 1))) {
        color = 'red';
      } else if (player.color === 'yellow' && ((row === 0 && col === 6) || (row >= 1 && row <= 4 && col === 5) || (row <= 1 && col >= 9))) {
        color = 'yellow';
      } else if (player.color === 'green' && ((row === 6 && col === 10) || (row === 5 && col >= 6 && col <= 9) || (row >= 9 && row <= 10 && col >= 9 && col <= 10))) {
        color = 'green';
      } else if (player.color === 'blue' && ((row === 10 && col === 4) || (row >= 6 && row <= 9 && col === 5) || (row >= 9 && col <= 1))) {
        color = 'blue';
      }
    });

    return color;
  };

  // Funkce pro zobrazení figurky na dané pozici
  const renderPiece = (row, col) => {
    // Hledání figurky, která odpovídá pozici řádku a sloupce
    const piece = pieces.find(p => {
      const { row: pieceRow, col: pieceCol } = getCoordinatesFromValue(p.position, p.color);
      return pieceRow === row && pieceCol === col;
    });

    // Pokud figurka existuje a má platnou pozici, vykreslíme ji
    if (piece && piece.position !== null) {
      return (
        <div className="piece" style={{ backgroundColor: piece.color, width: '70%', height: '70%' }}></div>
      );
    }

    // Pokud figurka nemá pozici (je null), vykreslíme ji s výchozím stylem
    if (piece && piece.position === null) {
      return (
        <div className="piece" style={{ backgroundColor: 'gray', width: '70%', height: '70%' }}></div>
      );
    }

    return null;
  };

  // Emitování eventu pro hru po hodu kostkou
  const emitGamePlayEvent = () => {
    if (socket) {
      console.log('Emituji event game:play');
      socket.emit('game:play');
    }
  };

  // Zpracování kliknutí na dlaždici (provedení tahu, pokud je to možné)
  const handleTileClick = (row, col) => {
    if (loading) {
      setError("Počkejte, prosím, dokud nebude dokončený aktuální tah.");
      return;
    }

    // Hledání figurky na kliknuté dlaždici
    const clickedPiece = pieces.find(p => getValueFromCoordinates(row, col, p.color) === p.position);

    if (clickedPiece) {
      const commonPosition = getValueFromCoordinates(row, col, clickedPiece.color);

      if (commonPosition !== null) {
        setLoading(true);
        setError(null);

        const payload = { commonPosition };
        console.log("Odesílám tah s pozicí:", payload);

        // Odeslání tahu na server
        socket.emit('game:movePiece', payload, (data) => {
          console.log('Přijata odpověď od serveru:', data);
        });
      } else {
        setError("Neplatný tah. Vyberte platnou dlaždici.");
      }
    } else {
      setError("Na této dlaždici není žádná figurka.");
    }
  };

  return (
    <div>
      {/* Tlačítko pro hod kostkou mimo desku */}
      <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'center' }}>
        <button 
          onClick={emitGamePlayEvent}
          style={{
            padding: '10px 20px', 
            fontSize: '16px', 
            cursor: 'pointer', 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            border: 'none', 
            borderRadius: '5px'
          }}
        >
          Hoď kostkou
        </button>
      </div>

      {/* Zobrazení zpráv o stavu a výsledku hodu kostkou */}
      {statusMessage && <div className="status-message">{statusMessage}</div>}
      {error && <div className="error">{error}</div>}
      {diceRoll !== null && <div className="dice-roll">Výsledek hodu: {diceRoll}</div>}

      {/* Vykreslení desky */}
      <div className="board">
        {Array.from({ length: gridSize * gridSize }).map((_, index) => {
          const row = Math.floor(index / gridSize);
          const col = index % gridSize;
          const tileColor = getTileColor(row, col);

          return (
            <div
              className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
              style={{
                backgroundColor: tileColor,
                width: '40px',
                height: '40px',
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                border: '1px solid #ccc',
                cursor: 'pointer',
              }}
              key={index}
              onClick={() => handleTileClick(row, col)}
            >
              {renderPiece(row, col)}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Board;
